package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPrehistoricBank2 {
    private const val T = "ප්‍රාග් ඓතිහාසික හා ආදි චිත්‍ර කලාව (ලොව හා ලංකාව)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික යුගයට අයත් ප්‍රකට ගුහා චිත්‍ර හමුවන කෑගල්ල දිස්ත්‍රික්කයේ ස්ථානය කුමක්ද?", "දොරවක කන්ද ගල් ලෙන", "සීගිරිය බිතු සිතුවම්", "දෙගල්දොරුව විහාරය", "තිවංක පිළිමගෙය", "කෑගල්ල දිස්ත්‍රික්කයේ අටාල ආසන්නයේ පිහිටි දොරවක කන්ද ලෙන ලංකාවේ වැදගත් ප්‍රාග් ඓතිහාසික ස්ථානයකි."),
        q("දොරවක කන්ද ගල් ලෙනෙහි පර්වත මතුපිට කොටා ඇති ප්‍රධාන සත්ව රූප මොනවාද?", "ඇතෙකු හා මුව පැටවෙකු වැනි රූප", "සිංහයෙකු හා හංස පූට්ටුවක්", "බයිසන් ගවයෙකු හා මැමත් රුවක්", "ගජසිංහ හා කිඳුරු රූප", "දොරවක කන්ද ලෙනෙහි පර්වතයේ නෙළන ලද ඇතෙකු, පැටවෙකු හා සූර්ය චන්ද්‍ර සංකේත දක්නට ලැබේ."),
        q("ශ්‍රී ලංකාවේ අනුරාධපුර දිස්ත්‍රික්කයේ ප්‍රාග් ඓතිහාසික ශිලා කෙටුම් හමුවන ප්‍රසිද්ධ ස්ථානය කුමක්ද?", "තන්තිරිමලේ බිල්ලෑව ලෙන", "වෙස්සගිරි ලෙන් සංකීර්ණය", "මිහින්තලේ කණ්ඨක චේතිය", "ඉසුරුමුණි විහාර ලෙන", "තන්තිරිමලේ රජමහා විහාර පරිශ්‍රයේ ඇති බිල්ලෑව ලෙන ආශ්‍රිතව පැරණි රේඛා චිත්‍ර හා කෙටුම් හමුවේ."),
        q("තන්තිරිමලේ ආදි චිත්‍රවල ප්‍රධාන වශයෙන් නිරූපණය කර ඇති කලා ස්වරූපය කුමක්ද?", "රතු හා සුදු වර්ණයෙන් ඇඳි සරල මිනිස් හා සත්ව රූප", "රන් ආලේපිත බුදු රූප", "තෙල් සායමින් ඇඳි රජ මාලිගා", "මහනුවර යුගයේ ජාතක කතා තීරු", "තන්තිරිමලේ ලෙන් සිතුවම්වල රතු ගුරුගල් හා සුදු අළු භාවිතයෙන් ඇඳි සරල රේඛා රූප දක්නට ඇත."),
        q("ශ්‍රී ලංකාවේ බදුල්ල දිස්ත්‍රික්කයේ පිහිටි ප්‍රාග් ඓතිහාසික රේඛා චිත්‍ර හමුවන ස්ථානයක් වන්නේ කුමක්ද?", "රාවණා ඇල්ල ගල් ලෙන", "මහියංගණ ධාතු ගර්භය", "මුතියංගණ විහාර මණ්ඩපය", "දෝව රජමහා විහාර පිළිමගෙය", "රාවණා ඇල්ල ගල් ලෙන ලංකාවේ මුල් මානව වාසස්ථාන හා ආදි රේඛා චිත්‍ර හමුවන ස්ථානයකි."),
        q("ශ්‍රී ලංකාවේ ආදිවාසී වැදි ජනතාව විසින් ගල් ලෙන්වල ඇඳ ඇති සිතුවම් හඳුන්වනු ලබන්නේ කෙසේද?", "වැදි ගුහා චිත්‍ර හෙවත් ශිලා රේඛා චිත්‍ර", "අනුරාධපුර සම්භාව්‍ය බිතුසිතුවම්", "මහනුවර තෙල් සායම් සිතුවම්", "සීගිරි ආලේප සිතුවම්", "වැදි ජනතාව ලෙන් බිත්තිවල ඇඟිලිවලින් ඇඳි රූප ලංකාවේ ගුහා චිත්‍ර කලාවේ වැදගත් කොටසකි."),
        q("අම්පාර හා මොණරාගල ප්‍රදේශවල වැදි ජනතාවගේ ගල් ලෙන් චිත්‍ර හමුවන ප්‍රකට ස්ථාන මොනවාද?", "බුදුගල, හෙනන්නේගල සහ රජගල ආශ්‍රිත ලෙන්", "පොළොන්නරුවේ ගල් විහාරය පමණි", "ගාල්ලේ කොටු පවුර පමණි", "මහනුවර දළදා මාලිගාව පමණි", "නැගෙනහිර හා ඌව පළාත්වල ලෙන් රැසක වැදි චිත්‍ර සුරක්ෂිතව පවතී."),
        q("ශ්‍රී ලංකාවේ වැදි ගුහා චිත්‍රවල සුදු පැහැය සෑදීමට බහුලව යොදා ගත්තේ කුමක්ද?", "දර අළු, කිරිමැටි සහ කෙළ හෝ ජලය", "ආනයනික චීන තීන්ත සහ ලාකඩ", "වේළන ලද බිත්තර සුදුමද පමණි", "රසදිය සහ තඹ කුඩු", "වැදි ජනතාව සුදු අළු, මකුළු මැටි සහ කුඩු කළ ගල් භාවිතයෙන් සුදු වර්ණය සාදා ගත්හ."),
        q("ශ්‍රී ලංකාවේ ආදි වැදි ගුහා චිත්‍රවල ඇඳ ඇති මිනිස් රූපවල ප්‍රධාන ලක්ෂණය කුමක්ද?", "කෙටි සරල රේඛාවලින් දුණු ඊතල අතැතිව දැක්වීම", "ඔටුණු හා ආභරණ පැළඳ සිටීම", "සංකීර්ණ සෙවණැලි සහිතව දැක්වීම", "රජ මාලිගාවක සිංහාසනාරූඪව දැක්වීම", "දුනු ඊතල සහිත දඩයක්කරුවන් හා කඹරගොයින්, කිඹුලන් වැනි සතුන් සරල රේඛාවෙන් ඇඳ තිබේ."),
        q("පේරාදෙණිය විශ්වවිද්‍යාලය හා පුරාවිද්‍යා දෙපාර්තමේන්තුව හඳුනා ගත් 'ගනේගම' හා 'කොන්දදෙණිය' ලෙන් චිත්‍ර අයත් වන්නේ කුමන වර්ගයටද?", "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික හා වැදි ගුහා සිතුවම්", "පෘතුගීසි බලකොටු බිතුසිතුවම්", "ඉන්දියානු මූගල් කුඩා චිත්‍ර", "යුරෝපීය පුනරුද සිතුවම්", "මෙම ගල් ලෙන්වල ඇති සරල සංකේතාත්මක චිත්‍ර ලංකාවේ ආදි චිත්‍ර උරුමයට අයත්ය."),
        q("දොරවක කන්ද ගල් ලෙන් කැණීම්වලින් තහවුරු වී ඇති ආදි මානව ක්‍රියාකාරකම් මොනවාද?", "ගල් ආයුධ, මැටි බඳුන් හා ධාන්‍ය භාවිතය", "මුද්‍රණ යන්ත්‍ර හා කඩදාසි නිෂ්පාදනය", "ලෝකඩ කාසි අච්චු ගැසීම", "වීදුරු කර්මාන්තශාලා පවත්වාගෙන යාම", "දොරවක කන්ද කැණීම්වලින් නවශිලා හා මධ්‍යශිලා අවධියේ ගල් ආයුධ හා මැටි බඳුන් සාක්ෂි හමුවිය."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික ගුහා චිත්‍රවල බහුලව දක්නට ලැබෙන 'කළු' වර්ණය ලබා ගැනීමට යොදා ගත් ද්‍රව්‍යය කුමක්ද?", "පිළිස්සුණු දැව අඟුරු", "තාර සහ භූමිතෙල්", "කළු රසායනික තීන්ත", "මිනිරන් සහ ඇලුමිනියම්", "ගිනි මැලවලින් ඉතිරි වන දැව අඟුරු කුඩු හෝ අඟුරු කූරු ඍජුවම ගල මත ඇඳීමට යොදා ගැනිණි."),
        q("ලංකාවේ ආදි ගුහා සිතුවම් අතර 'පුංචි කිරිඳිඔය', 'මාන්දගල' හා 'හමංගල' ප්‍රදේශවල චිත්‍රවල විශේෂත්වය කුමක්ද?", "අලියා, දිවියා සහ කබරගොයා වැනි වන සතුන් ඇඳ තිබීම", "ජාතක කතා පෙළට ඇඳ තිබීම", "බුදු රජාණන් වහන්සේගේ දිව්‍ය ලෝක දර්ශන තිබීම", "වරාය හා නැව් සිතුවම් කර තිබීම", "මෙරට වනාන්තරවල ජීවත් වන වන සතුන් හා දඩයම් දර්ශන සරලව නිරූපණය කර ඇත."),
        q("වැදි ජනතාව තම ලෙන් සිතුවම් ඇඳීමේදී පින්සල් වෙනුවට බහුලව භාවිත කළ අංගය කුමක්ද?", "අතේ ඇඟිලි සහ තැළූ කෝටු කැබලි", "සියුම් මුව රෝම පින්සල්", "පිහාටු සහ වානේ පෑන් තුඩු", "රබර් රෝලර් සහ ස්පොන්ජි", "අළු හෝ මැටි දියරයේ ගිල්වූ දබරැඟිල්ලෙන් ගල් බිත්තියේ ඉරි ඇඳීම වැදි චිත්‍රවල ප්‍රධාන ලක්ෂණයකි."),
        q("ශ්‍රී ලංකාවේ 'තන්තිරිමලේ' ලෙන් සිතුවම්වල ඇති සූර්ය සංකේත හා චන්ද්‍ර සංකේතවලින් ප්‍රකාශ වන්නේ කුමක්ද?", "ස්වභාවධර්මයේ බලවේග වන්දනය හා කාල ගණනය", "නූතන ගුවන් විදුලි සංඥා", "රජයේ මුද්‍රා හා පාර්ලිමේන්තු සලකුණු", "ලන්දේසි නාවික සලකුණු", "හිරු, සඳු හා ජ්‍යාමිතික හැඩතල ආදි මානවයාගේ ස්වභාවධර්ම විශ්වාස හා සන්නිවේදන සංකේත විය."),
        q("පුරාණ ලංකාවේ ලෙන් සිතුවම් අධ්‍යයනය කළ 'සී. ජී. සෙලිග්මාන්' විද්වතා වැඩිපුර පර්යේෂණ කළේ කුමන ජන කොටසකගේ කලාව ගැනද?", "ශ්‍රී ලංකාවේ වැදි ජනතාවගේ කලාව", "පොළොන්නරුවේ චෝල කලාකරුවන්ගේ කලාව", "මහනුවර නායක්කර් වංශික කලාව", "කෝට්ටේ පෘතුගීසි සිතුවම් කලාව", "සෙලිග්මාන් යුවළ විසින් වැදි ජනතාවගේ ගුහා චිත්‍ර හා සංස්කෘතිය පිළිබඳ ග්‍රන්ථ රචනා කර ඇත."),
        q("ශ්‍රී ලංකාවේ ලෙන් චිත්‍ර සම්ප්‍රදායේ 'වැලිමඩ' හා 'උඩරට' ප්‍රදේශවලට වඩා 'බින්තැන්න' හා 'අම්පාර' ප්‍රදේශවල ගුහා චිත්‍ර සුලබ වීමට හේතුව කුමක්ද?", "වියළි කලාපයේ හුදකලා ගල් ලෙන් හා ආදිවාසී ජනාවාස පැවතීම", "වියළි කලාපයේ වර්ණ කර්මාන්තශාලා තිබීම", "තෙත් කලාපයේ ගල් පර්වත කිසිවක් නොතිබීම", "වැදි ජනතාව මුහුදු යාත්‍රා චිත්‍ර ඇඳි බැවින්", "බින්තැන්න හා නැගෙනහිර වනාන්තරවල ආදිවාසී ජනාවාස හා ස්වභාවික ගල් ලෙන් බහුල විය."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික ගල් ලෙන්වල 'මැටි ආලේපිත පසුබිමක්' (Plaster) නොමැතිව කෙළින්ම ගල මත ඇඳීමේ ප්‍රතිඵලය කුමක්ද?", "රූප බොහෝ විට රළු හා නොගැඹුරු සටහන් වීම", "චිත්‍ර ඉතා සිනිඳු ඔප දැමූ තෙල් සායම් බවට පත්වීම", "බදාමය ගැලවී යාමෙන් චිත්‍ර රැකීම", "වර්ණවල දිලිසෙන වීදුරු ගතියක් ඇතිවීම", "සකස් කළ බදාමයක් නොමැති රළු ගල් මතුපිට නිසා රේඛා කෙටි හා රළු ස්වභාවයක් ගනී."),
        q("දොරවක කන්ද ගුහාවේ 'හෙනරාජ පර්වත කෙටුම්' ලෙස හඳුන්වන රූප සටහන් නිමවා ඇත්තේ කුමන තාක්ෂණයෙන්ද?", "පර්වත මතුපිට උල් ආයුධයකින් කෙටීමෙන්", "කිරිමැටි තට්ටු උඩට අඹා ඇලවීමෙන්", "තෙල් සායමින් රාමු ඇඳ පිරවීමෙන්", "රතු පැහැති සේද රෙදි ඇලවීමෙන්", "දොරවක කන්ද කෙටුම් තියුණු ගල් හෝ ලෝහ උපකරණයකින් පර්වතය කොටා සකස් කර ඇත."),
        q("ශ්‍රී ලංකාවේ ආදි චිත්‍රවල දක්නට ලැබෙන 'කබරගොයා' හා 'තලගොයා' වැනි රූපවලින් පිළිබිඹු වන්නේ කුමක්ද?", "ආහාර සඳහා සතුන් දඩයම් කිරීමේ එදිනෙදා ජීවිතය", "රාජකීය ලාංඡන හා කොඩි සලකුණු", "සංගීත භාණ්ඩ තැනීමේ සැලසුම්", "තාරකා විද්‍යාත්මක රාශි චක්‍රය", "ආදිවාසීන්ගේ එදිනෙදා ආහාර රටාවට හා පරිසරයට සම්බන්ධ සතුන් එහි නිරූපිතය."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික මානවයාගේ ප්‍රධාන සංස්කෘතික සාධක හඳුනාගත් 'බෙල්ලන්බැඳි පැලැස්ස' අයත් වන්නේ කුමන දිස්ත්‍රික්කයටද?", "රත්නපුර දිස්ත්‍රික්කය", "යාපනය දිස්ත්‍රික්කය", "මාතර දිස්ත්‍රික්කය", "පුත්තලම දිස්ත්‍රික්කය", "උඩවලව ආසන්නයේ බෙල්ලන්බැඳි පැලැස්ස මධ්‍යශිලා මානව සැකිලි හා ආයුධ හමුවූ ප්‍රකට ස්ථානයකි."),
        q("ලංකාවේ 'රාජගලතැන්න' සහ 'කොමාරිගල' වැනි ස්ථානවල ආදි ලෙන් සිතුවම් මත පසුකාලීන බෞද්ධ සිතුවම් පවතින්නේ ඇයි?", "ආදි ලෙන් පසුකාලීනව භික්ෂු ආරාම බවට පත් වූ බැවින්", "වැදි ජනතාව විහාරස්ථාන කඩා දැමූ බැවින්", "රජවරුන් පැරණි චිත්‍ර විකුණා දැමූ බැවින්", "සියලු චිත්‍ර විදේශිකයන් විසින් ඇඳි බැවින්", "ආදි මානවයා විසූ ගල් ලෙන් කටාරම් කොටා පසුව සංඝාවාස බවට පත් කර තිබීම ඊට හේතුවයි."),
        q("කටාරම් කෙටීම (Drip-ledge cutting) යනු පසුකාලීනව ගල් ලෙන් චිත්‍රවලට සිදු කළ කුමන ආකාරයේ ආරක්ෂාවක්ද?", "වැසි ජලය ගුහාව ඇතුළට ගලා ඒම වැළැක්වීම", "හිරු එළිය ලෙන ඇතුළට ගැනීම", "සතුරන්ගේ ඊතල නවතා දැමීම", "ලෙන තුළ වායු සමීකරණය කිරීම", "ලෙන් මුවදොරට ඉහළින් පේළියක් කෙටීමෙන් පර්වතය දිගේ එන වැසි දිය ලෙනට ඇතුළු වීම වළකී."),
        q("ශ්‍රී ලංකාවේ ක්‍රි.පූ. 6 වන සියවසට පෙර පැවති 'බලංගොඩ මානවයා' අයත් වන්නේ කුමන ශිලා යුගයටද?", "මධ්‍යශිලා හෙවත් මේසොලිතික යුගය", "පූර්ව කේම්බ්‍රීය යුගය", "මහා කාර්මික විප්ලව යුගය", "මහනුවර නායක්කර් යුගය", "ලංකාවේ වසර 30,000 සිට 3,000 දක්වා විසූ බලංගොඩ මානවයා මධ්‍යශිලා සංස්කෘතිය නියෝජනය කරයි."),
        q("ශ්‍රී ලංකාවේ 'කුරුණෑගල දිස්ත්‍රික්කයේ' නවශිලා හා ප්‍රාග් ඓතිහාසික සාධක හමුවූ ලෙන කුමක්ද?", "හුළුගල්ල හෝ අලවල පොත්ගුල් ලෙන", "නල්ලූර් කෝවිල", "මඩකලපුව ලන්දේසි කොටුව", "ගාලු කොටු ප්‍රදීපාගාරය", "අලවල පොත්ගුල් ලෙන ආශ්‍රිතව ප්‍රාග් ඓතිහාසික මානව ජනාවාස සාක්ෂි පුරාවිද්‍යාඥයන් සොයාගෙන ඇත."),
        q("ආදි චිත්‍රවල 'කුඩා ජ්‍යාමිතික සලකුණු' යනු අනාගත කුමන මානව හැකියාවේ පූර්වගාමියා ලෙස සැලකේද?", "ලේඛන කලාව හා අක්ෂර මාලාව බිහිවීම", "රසායනික පොහොර නිපදවීම", "විදුලි බලය උත්පාදනය කිරීම", "වාෂ්ප එන්ජින් සෑදීම", "වස්තූන් සංකේතවත් කරන චිත්‍රමය සලකුණු ක්‍රමයෙන් පික්ටොග්‍රෑම් හා අක්ෂර බවට පරිණාමය විය."),
        q("ප්‍රාග් ඓතිහාසික කලා නිර්මාණ අධ්‍යයනයේදී 'වැඩුණු මුවන්' රූපයක ඇති ප්‍රමාණ අනුපාත වෙනස් වන්නේ කෙසේද?", "අං හෝ උදරය වැනි අංග විශාල කර දැක්වීම", "සෑම අවයවයක්ම කෝදුවෙන් මැන ඇඳීම", "වස්තූන් සියල්ල ත්‍රිකෝණ ලෙස ඇඳීම", "හිස සම්පූර්ණයෙන් අත්හැර දැමීම", "සශ්‍රීකත්වය හෝ ශක්තිය හඟවන අවයව අතිශයෝක්තියෙන් විශාල කර දැක්වීම ආදි කලාවේ ලක්ෂණයකි."),
        q("ශ්‍රී ලංකාවේ ආදි ගුහා චිත්‍ර පිළිබඳව මූලික පුරාවිද්‍යාත්මක වාර්තාකරණයක යෙදුණු විද්වතා කවුද?", "ආචාර්ය පී. ඊ. පී. දැරණියගල මහතා", "මහාචාර්ය විමල් බලගල්ලේ මහතා", "ආචාර්ය ලෙස්ටර් ජේම්ස් පීරිස් මහතා", "ඩබ්ලියු. ඩී. අමරදේව මහතා", "පී. ඊ. පී. දැරණියගල මහතා ලංකාවේ ප්‍රාග් ඓතිහාසික මානව විද්‍යාව හා ගුහා කලාව පිළිබඳ පුරෝගාමියෙකි."),
        q("ප්‍රාග් ඓතිහාසික චිත්‍රවල ඇඳි 'සමපාතික නොවන පරිමාණය' (Hieratic scale) යනු කුමක්ද?", "වැදගත්කම අනුව රූප විශාල හෝ කුඩා කර ඇඳීම", "වර්ණවල දීප්තිය අනුව රූප පෙළගැස්වීම", "පසුබිම් රූප ඉදිරිපස රූපවලට වඩා ලොකු කිරීම", "සියලු සතුන් එකම උසකින් ඇඳීම", "මිනිසාට වඩා දඩයම් කරන විශාල සතා හෝ ප්‍රධාන සංකේතය විශාලව ඇඳීම වැදගත්කම පෙන්වයි."),
        q("මහඔය හා නුවරගල ආශ්‍රිත ගල් ලෙන් චිත්‍ර අතර දක්නට ලැබෙන සුවිශේෂී සත්ව රූපය කුමක්ද?", "සුවිශාල අලි රූප සහ පිහිටි ඇතා", "රන්වන් මකර රූප", "පියාපත් ඇති අශ්ව රූප", "ජල කිඳුරු රූප", "මහඔය නුවරගල ලෙන් චිත්‍රවල අලි ඇතුන් හා දඩයම් දර්ශන සුදු හා අළු පැහැයෙන් ඇඳ ඇත."),
        q("නවශිලා යුගයේ චිත්‍ර කලාව හා පුරාශිලා යුගයේ චිත්‍ර කලාව අතර 'ශිල්පීය අරමුණ' වෙනස් වන්නේ කෙසේද?", "දඩයම් අභිචාරයේ සිට ගෘහ භාණ්ඩ අලංකරණය දක්වා", "පොත් මුද්‍රණයේ සිට රූපවාහිනිය දක්වා", "තෙල් සායමේ සිට ජල සායම් දක්වා", "වීදුරු කැටයමේ සිට ප්ලාස්ටික් දක්වා", "ස්ථාවර කෘෂිකාර්මික ජීවිතයත් සමඟ චිත්‍ර කලාව ආභරණ, රෙදි හා මැටි බඳුන් අලංකරණයට යොමු විය."),
        q("ශ්‍රී ලංකාවේ 'ගෝනගම්පොල' හා 'පදියතලාව' ආශ්‍රිත ගුහා චිත්‍ර ආරක්ෂා කිරීමට ඇති ප්‍රධාන තර්ජනය කුමක්ද?", "කාලගුණික ඛාදනය හා මිනිස් කුරුටු ගෑම්", "සමුද්‍රික ජල ගැලීම් හා සුළි සුළං", "නගරබද කර්මාන්තශාලා දුමාරය", "විදුලි ආලෝක පහන්වල තාපය", "වැසි, හිරු රශ්මිය, දිලීර සහ අවිධිමත් නරඹන්නන් අතින් සිදුවන හානි මෙම චිත්‍රවලට තර්ජනයකි."),
        q("ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර සංරක්ෂණයේදී 'කලා කෘති ස්පර්ශ නොකිරීම' වැදගත් වන්නේ ඇයි?", "අතේ ඇති තෙල් හා තෙතමනයෙන් ස්වභාවික වර්ණක ඉවත් වන බැවින්", "වර්ණකවල විෂ රසායන අතේ තැවරෙන බැවින්", "ගල් බිත්ති එසැණින් කඩා වැටෙන බැවින්", "චිත්‍රයේ ඇති විදුලි ආරෝපණය වදින බැවින්", "මැලියම් ස්ථිර නොවූ ස්වභාවික ඛනිජ වර්ණ ස්පර්ශ කිරීමෙන් පහසුවෙන් මැකී යා හැක."),
        q("ප්‍රංශයේ 'නියෝ' (Niaux) ගුහාවේ කළු රේඛාවෙන් ඇඳි බයිසන් ගව රූපවල භාවිත කර ඇති ප්‍රධාන තාක්ෂණය කුමක්ද?", "සියුම් චාලන රේඛා (Contour Drawing) මගින් හැඩය මතු කිරීම", "සම්පූර්ණ වර්ණ ආලේපන කුට්ටි යෙදීම", "ලෝහ තහඩු කපා පර්වතයේ ඇලවීම", "සුදු පැහැති තෙල් සායමින් පසුබිම වැසීම", "සංකීර්ණ වර්ණ පිරවීමකින් තොරව නිවැරදි අඛණ්ඩ බාහිර රේඛාවෙන් පමණක් සිරුර දක්වා ඇත."),
        q("ආදි චිත්‍රවල 'අශ්වයෙකු දුවන අවස්ථාවේ පාද අටක් ඇඳීම' වැනි දර්ශනවලින් ප්‍රකාශ වන අදහස කුමක්ද?", "සත්වයාගේ වේගවත් චලනය පෙන්වීම", "සත්වයාට පාද අටක් ඇති බව විශ්වාස කිරීම", "චිත්‍ර ශිල්පියාට ගණන් කිරීමට නොහැකි වීම", "කලා කෘතිය අසම්පූර්ණව අත්හැර දැමීම", "බහු රූප හෝ අමතර පාද ඇඳීම මගින් සිනමාත්මක චලන හැඟීමක් ජනිත කර තිබේ."),
        q("දොරවක කන්ද ලෙනෙහි 'ලංකාවේ පැරණිතම ගුහා කෙටුම්' කුමන වර්ෂ සීමාවට අයත් බව පුරාවිද්‍යාඥයෝ අනුමාන කරත්ද?", "ක්‍රි.පූ. 4300 පමණ නවශිලා හෝ මධ්‍යශිලා අවධිය", "ක්‍රි.ව. 1505 පෘතුගීසි ආගමන සමය", "ක්‍රි.ව. 1815 ඉංග්‍රීසි යටත්විජිත සමය", "ක්‍රි.ව. 1055 පොළොන්නරු යුගය", "රේඩියෝ කාබන් කාල නිර්ණ අනුව දොරවක කන්ද ක්‍රි.පූ. සිව්වන සහස්‍රය තරම් පැරණි බව හෙළිවේ."),
        q("පුරාශිලා යුගයේ සිතුවම් 'සංස්කෘතික මානව විද්‍යාවට' වැදගත් වන්නේ කුමන හේතුවක් නිසාද?", "ලිඛිත ඉතිහාසයට පෙර මානව සිතුවිලි හා ඇදහිලි හෙළි කරන බැවින්", "පැරණි රාජ්‍ය ව්‍යවස්ථා එහි ලියා ඇති බැවින්", "කෘෂිකාර්මික බදු වාර්තා එහි ඇති බැවින්", "විදේශීය වෙළඳ ගිවිසුම් එහි ඇති බැවින්", "අකුරු බිහිවීමට පෙර මිනිසාගේ භීතිය, අභිචාර හා නිර්මාණශීලීත්වය දැනගැනීමට ඇති එකම මග මෙයයි."),
        q("ලංකාවේ 'ලෙනම' හා 'ගමකන්ද' ප්‍රදේශවල ආදි ලෙන් චිත්‍ර අධ්‍යයනයේදී දැකිය හැකි මාධ්‍ය ලක්ෂණය කුමක්ද?", "අළු හා රතු ගුරුගල් මිශ්‍ර රළු ඇඟිලි සටහන්", "චීන පින්සල් පහරවල් සහිත තීන්ත රූප", "රන් හා රිදී පත්‍ර ඇලවූ බුදු රූප", "පැස්ටල් කූරුවලින් කඩදාසියේ ඇඳි රූප", "බොහෝ වැදි ගුහා සිතුවම්වල දේශීය අළු, කිරිමැටි හා ගුරුගල් ඇඟිල්ලෙන් ආලේප කර ඇත."),
        q("ආදි කලාවේ 'මහා ශිලා ස්මාරක' (Megalithic Monuments) යනු කුමක්ද?", "බදාම නොමැතිව දැවැන්ත ගල් කුට්ටිවලින් තැනූ ඉදිකිරීම්", "මැටියෙන් පමණක් තැනූ කුඩා ගෙවල්", "ලී කඳන්වලින් තැනූ ජල පාලම්", "ලෝකඩ තහඩුවලින් තැනූ පිළිම", "ස්ටෝන්හෙන්ජ් හා ඩොල්මන් මෙන් යෝධ ගල් කුට්ටි එක මත එක තබා තැනූ පැරණි ස්මාරකයි."),
        q("නවශිලා යුගයේදී 'පබළු නිෂ්පාදනය' (Bead making) කලා කර්මාන්තයක් ලෙස දියුණු වූයේ කුමන ද්‍රව්‍ය භාවිතයෙන්ද?", "මැටි, ඇටකටු, කාර්නීලියන් ගල් හා සිප්පි කටු", "ප්ලාස්ටික්, නයිලෝන් හා සින්තටික් ද්‍රව්‍ය", "ඇලුමිනියම්, ටයිටේනියම් හා රසදිය", "කෘත්‍රිම රේසින් හා ඇක්‍රිලික්", "ඉබ්බන්කටුව වැනි අඩවිවලින් පවා කාර්නීලියන් හා මැටි පබළු නිර්මාණ හමු වී තිබේ."),
        q("ප්‍රාග් ඓතිහාසික මිනිසා ගල් ආයුධ නිර්මාණයේදී පවා 'සමමිතිය හා හැඩය' කෙරෙහි අවධානය යොමු කළ බව පෙනෙන්නේ කුමකින්ද?", "ද්වි-මුහුණත් අත් පොරෝ (Hand axes) ඉතා අලංකාර හැඩයට පතුරු ගැසීමෙන්", "ගල් ආයුධ මත රන් තීන්ත ආලේප කිරීමෙන්", "ප්ලාස්ටික් අච්චුවල දමා ගල් වාත්තු කිරීමෙන්", "ගල් ආයුධවලට රිදී මිටි සවි කිරීමෙන්", "ප්‍රායෝගික අවශ්‍යතාව ඉක්මවා සමමිතික හැඩයට ගල් ආයුධ පතුරු ගැසීම මුල් සෞන්දර්ය හැඟීම පෙන්වයි."),
        q("ප්‍රංශයේ 'ෆොන්ට්-ඩි-ගෞම්' (Font-de-Gaume) ගුහාව සුවිශේෂී වන්නේ කුමන ප්‍රාග් ඓතිහාසික කලා ලක්ෂණය නිසාද?", "මැමත් හා පිනිමුවන්ගේ බහුවර්ණ සිතුවම් අදටත් සුරක්ෂිත වීම", "ලොව පැරණිතම මැටි බඳුන් ගබඩාව එහි පිහිටීම", "ගුහාව සම්පූර්ණයෙන් කිරිගරුඬවලින් කැටයම් කර තිබීම", "එහි සියලු සිතුවම් තෙල් සායමින් ඇඳ තිබීම", "ෆොන්ට්-ඩි-ගෞම් ප්‍රංශයේ මහජනයාට තවමත් නැරඹිය හැකි ප්‍රකට බහුවර්ණ ගුහා චිත්‍ර අඩවියකි."),
        q("ලංකාවේ ප්‍රාග් ඓතිහාසික ශිලා සිතුවම් 'සන්නිවේදන මාධ්‍යයක්' ලෙස ක්‍රියා කළ ආකාරය කුමක්ද?", "දඩයම් කලාප, අනතුරු සහ අභිචාර දැනුම් දීම", "මැතිවරණ ප්‍රචාරණ පුවරු ප්‍රදර්ශනය කිරීම", "විදේශීය වෙළඳ නැව්වලට ගාස්තු පැනවීම", "පුවත්පත් වාර්තා දෛනිකව ප්‍රකාශ කිරීම", "ආහාර සොයා යන මාර්ග, සතුන් ගැවසෙන තැන් හා ගෝත්‍රික සලකුණු රූප මගින් දැක්වීය."),
        q("ප්‍රාග් ඓතිහාසික චිත්‍රවල 'කලාලෝභී' හෙවත් සෞන්දර්යාත්මක අගය හඳුනා ගත් පළමු නූතන ශිල්පීන් අතර පිකාසෝ කියා සිටියේ කුමක්ද?", "ඇල්ටමීරා ගුහා චිත්‍රවලට පසු කලාව තවමත් පරාජය වී නැති බව", "ගුහා චිත්‍ර කිසිදු කලාත්මක වටිනාකමකින් තොර බව", "ගුහා චිත්‍ර ළමුන්ගේ කුරුටු සටහන් පමණක් බව", "තෙල් සායම් නොමැති නිසා ඒවා අසාර්ථක බව", "ලැස්කෝ හා ඇල්ටමීරා සිතුවම් දුටු නූතන ශිල්පීහු ආදි චිත්‍රවල ප්‍රබල රේඛා කුසලතාව අගය කළහ."),
        q("ශ්‍රී ලංකාවේ 'පූනාගල' සහ 'ගල්ගමුව' ප්‍රදේශවල හමු වූ ශිලා කෙටුම් හා චිත්‍රවල දක්නට ලැබෙන ප්‍රධාන ලක්ෂණය කුමක්ද?", "ජ්‍යාමිතික රේඛා, වෘත්ත හා සත්ව සංකේත", "චීන ද්‍රව්‍ය හා බටහිර අක්ෂර", "මහනුවර පෙරහැර දර්ශන", "වෛද්‍ය ශාස්ත්‍රීය රූපසටහන්", "ඉර, හඳ, දුනු හා සතුන් හඟවන සරල රේඛාත්මක සංකේත ලංකාවේ ආදි ලෙන්වල බහුලය."),
        q("ගුහා සිතුවම්වල භාවිත කළ 'රතු ගුරුගල්' (Red Ochre) ශරීර ආලේපන හා භූමදාන චාරිත්‍ර සඳහා ද යොදා ගත්තේ ඇයි?", "රතු පැහැය රුධිරය හා ජීව ශක්තිය සංකේතවත් කළ බැවින්", "රතු පැහැය අඳුරේ ඉතා හොඳින් දිලිසෙන බැවින්", "රතු පැහැයෙන් ශීතල සම්පූර්ණයෙන් නවතින බැවින්", "වෙනත් කිසිදු පැහැයක් පොළොවේ නොතිබූ බැවින්", "ජීවයේ හා නැවත ඉපදීමේ සංකේතයක් ලෙස ආදි මානවයා මෘතදේහ මත පවා රතු ගුරුගල් ඉස ඇත."),
        q("ප්‍රංශයේ 'කොස්කර්' (Cosquer) ගුහාව පුරාවිද්‍යාත්මකව අතිශය විශේෂිත වන්නේ කුමන පිහිටීම නිසාද?", "ගුහාවේ පිවිසුම මුහුදු මට්ටමට යටින් පිහිටා තිබීම", "ගුහාව හිමාල කඳු මුදුනේ පිහිටා තිබීම", "ගුහාව සක්‍රීය ගිනි කන්දක් ඇතුළත තිබීම", "ගුහාව සම්පූර්ණයෙන්ම රනින් නිමවා තිබීම", "හිම යුගයෙන් පසු මුහුදු මට්ටම ඉහළ යාම නිසා මෙහි පිවිසුම මීටර් 37ක් මුහුද යට පිහිටයි."),
        q("කොස්කර් ගුහාවේ සිතුවම්වල දක්නට ලැබෙන, වෙනත් යුරෝපීය ගුහාවල ඉතා දුර්ලභ සත්ව රූප මොනවාද?", "පෙන්ගුයින්, සීල් මසුන් සහ ජෙලිෆිෂ් වැනි සමුද්‍ර ජීවීන්", "සිංහයන්, ව්‍යාඝ්‍රයන් සහ මොනරුන්", "කැන්ගරුවන් සහ කෝලා වලසුන්", "ජිරාෆ් සහ රයිනෝසිරස් සතුන්", "මුහුදුබඩ පිහිටි නිසා මෙහි අශ්වයන්ට අමතරව සීල් මසුන් හා පෙන්ගුයින් පක්ෂීන් ඇඳ ඇත."),
        q("පුරාශිලා මිනිසා විසින් නිර්මාණය කළ 'අත් සලකුණුවල' සමහර විට ඇඟිලි අඩු වී පෙනීමට එක් හේතුවක් ලෙස විද්වතුන් දක්වන්නේ කුමක්ද?", "ඇඟිලි නවා ගෙන සංඥා භාෂාවක් ලෙස සටහන් තැබීම", "මිනිසුන්ට ඇඟිලි හතර බැගින් පමණක් තිබීම", "තීන්ත බටය අවහිර වී වැරදීමක් සිදුවීම", "වීදුරු තහඩු මත ඇඳීම නිසා මැකී යාම", "දඩයම් සංඥා භාෂාවේදී මෙන් ඇඟිලි කිහිපයක් නවා අත තබා සලකුණු පිඹ ඇති බව සැලකේ."),
        q("ශ්‍රී ලංකාවේ 'මාන්දගල' වැදි ගුහා සිතුවම්වල දැකිය හැකි මානව-සත්ව සබඳතාව පෙන්වන දර්ශනය කුමක්ද?", "අලියෙකු පිට නැගුණු හෝ දුනු ගත් දඩයක්කරුවන්", "රථයක නැගුණු රාජ කුමාරවරුන්", "සිංහාසනයක වැඩ සිටින දෙවිවරුන්", "විශ්වවිද්‍යාලයක ඉගෙනුම ලබන සිසුන්", "අලි, මුවන් සහ බල්ලන් සමඟ දඩයමේ යන රූප සරල රේඛාවලින් මාන්දගල ලෙනෙහි ඇඳ ඇත."),
        q("ප්‍රාග් ඓතිහාසික කලා ඉතිහාසයේ 'පෙට්‍රොග්ලිෆ්' සහ 'පික්ටොග්‍රෑම්' අතර මූලික තාක්ෂණික වෙනස කුමක්ද?", "පෙට්‍රොග්ලිෆ් ගල හාරා කොටන අතර පික්ටොග්‍රෑම් වර්ණයෙන් අඳියි", "පෙට්‍රොග්ලිෆ් කඩදාසියේද පික්ටොග්‍රෑම් රෙදිවලද අඳියි", "පෙට්‍රොග්ලිෆ් ජල සායම්ද පික්ටොග්‍රෑම් තෙල් සායම්ද වේ", "දෙකම මැටි පෝරණුවල පුළුස්සා සාදන පිඟන් වේ", "ගල කෙටීමෙන් සෑදෙන රූප පෙට්‍රොග්ලිෆ් වන අතර ගල මතුපිට වර්ණ ගැන්වීමෙන් පික්ටොග්‍රෑම් සෑදේ."),
        q("ස්පාඤ්ඤයේ 'එල් කැස්ටිලෝ' (El Castillo) ගුහාවේ ඇති රතු තැටි සහ අත් සලකුණුවල වයස කොපමණ පමණ වේද?", "වසර 40,000කට වඩා පැරණිය", "වසර 500ක් පමණ පැරණිය", "වසර 1,500ක් පමණ පැරණිය", "වසර 2,500ක් පමණ පැරණිය", "යුරේනියම්-තෝරියම් කාල නිර්ණය අනුව මෙම ගුහාවේ රතු තැටි වසර 40,800කට වඩා පැරණි බව තහවුරු විය."),
        q("පුරාශිලා ගුහා චිත්‍රවල ඇඳි සතුන්ගේ ඇස් සහ අං 'පැතිකඩ දර්ශනයට' නොගැළපෙන ලෙස ඉදිරියට හරවා ඇඳීමෙන් සිදු කළේ කුමක්ද?", "සත්වයාගේ ප්‍රධාන ලක්ෂණ වඩාත් පැහැදිලිව හඳුනාගැනීමට සැලැස්වීම", "චිත්‍ර ශිල්පියාගේ දෘෂ්ටි දෝෂ පෙන්වීම", "වර්ණ ඉතිරි කර ගැනීමට උත්සාහ කිරීම", "පසුකාලීනව චිත්‍රය වෙනස් කිරීම", "සත්වයාගේ හඳුනාගැනීමේ ලක්ෂණ (අං යුගලය, කන්) වඩාත් ප්‍රබලව පෙන්වීමට මෙම ක්‍රමය යොදා ගති."),
        q("ලංකාවේ 'සේරුනුවර' හා 'ගෝනගල' ආදි ලෙන් චිත්‍රවල 'ඇඟිලි පහරවල්' වෙනුවට ඇතැම් ස්ථානවල තිත් රටා දක්නට ලැබෙන්නේ කෙසේද?", "කෝටු කැබැල්ලක අග තීන්තවල ඔබා ගල මත තැබීමෙන්", "විදුලි පින්සල්වලින් ඉසීමෙන්", "අච්චු කඩදාසි තබා මුද්‍රණය කිරීමෙන්", "පිහි තුඩෙන් ගල සූරා පිරවීමෙන්", "කෝටු කැබැල්ලක හෝ ඇඟිලි තුඩක ආධාරයෙන් සරල තිත් රටා හා සත්ව සිරුරු පිරවීම් සිදු කර ඇත."),
        q("ප්‍රාග් ඓතිහාසික මූර්ති අතරින් 'ලෝකයේ පැරණිතම මිනිස් මුහුණේ කැටයම' ලෙස සැලකෙන චෙක් නිර්මාණය කුමක්ද?", "ඩොල්නි වෙස්ටෝනිස් ඇත්දත් කාන්තා හිස", "ගීසාහි මහා ස්පින්ක්ස් මුහුණ", "නෙෆර්ටිටි රැජිනගේ පිළිමය", "සමනල කන්දේ පාද සටහන", "ඇත්දත්වලින් කැටයම් කළ වසර 26,000ක් පැරණි කාන්තා මුහුණක් එහිදී හමුවී ඇත."),
        q("ආදි චිත්‍ර කලාව හා නූතන කුඩා දරුවන්ගේ චිත්‍ර අතර පවතින ප්‍රධාන සංකල්පීය සමානකම කුමක්ද?", "බාහිර පෙනුමට වඩා තමා දන්නා වැදගත් කොටස් ප්‍රකාශ කිරීම", "තෙල් සායම් හා වාර්නිෂ් බහුලව භාවිත කිරීම", "රේඛීය දෘෂ්ටිකෝණ ගණිත නීති අනුගමනය කිරීම", "නිශ්චිත කලා ගුරුකුල රීති පිළිපැදීම", "පසුබිම් නොමැතිව තමාට වැදගත් වන අංග විශාලව ඇඳීමේ බුද්ධිමය ස්වභාවය දෙකෙහිම පොදුය."),
        q("ශ්‍රී ලංකාවේ 'මහාශිලා' සංස්කෘතියට අයත් ප්‍රධාන සුසාන ක්‍රමවේදය කුමක්ද?", "සිස්ට් (Cist) හෙවත් ගල් පෙට්ටි සුසාන සහ බඳුන් සුසාන", "පිරමීඩ තුළ මමී තැන්පත් කිරීම", "මුහුදු යාත්‍රාවල දමා පා කිරීම", "මහා ගල් කුළුණු මත තැබීම", "ඉබ්බන්කටුව හා පොම්පරිප්පුව ආදී ස්ථානවලින් ගල් පුවරු සුසාන හා මැටි බඳුන් සුසාන හමුවේ."),
        q("ආදි මානවයා විසින් ගුරුගල් 'පුළුස්සා' රත් කිරීමෙන් වර්ණ කලාවේ ලබා ගත් වැදගත් සොයාගැනීම කුමක්ද?", "කහ ගුරුගල් රත් කිරීමෙන් තද රතු හා දම් පැහැය ලබාගත හැකි බව", "වීදුරු බඳුන් ස්වයංක්‍රීයව නිපදවිය හැකි බව", "ගුරුගල් රත් කළ විට නිල් පැහැ වන බව", "අඟුරු රත් කිරීමෙන් සුදු පැහැ වන බව", "යකඩ ඔක්සයිඩ් අඩංගු කහ ගුරුගල් ගින්දරෙන් රත් කළ විට තද රතු පැහැයට හැරෙන බව ඔවුහු දැන සිටියහ."),
        q("ප්‍රාග් ඓතිහාසික ගුහා චිත්‍රවල ඇඳ ඇති සතුන්ගෙන් බහුතරයක් 'නිශ්චිත සෘතුමය' (ලොම් වැඩුණු හෝ කෙටි) ලක්ෂණ පෙන්වන්නේ ඇයි?", "වසරේ විවිධ කාලවලදී අභිචාර පැවැත්වූ බැවින්", "කලාකරුවන් කාලගුණ වාර්තා තැබූ බැවින්", "සතුන්ගේ සිරුරේ පිහාටු තිබූ බැවින්", "එකම දිනයේදී සියලු චිත්‍ර ඇඳ අවසන් කළ බැවින්", "වසන්ත හා ශරත් සෘතුවල සතුන්ගේ ලොම් ස්වභාවය පවා නිරීක්ෂණය කර ඇඳීම ආදි ශිල්පියාගේ තීක්ෂණ බව පෙන්වයි."),
        q("ඉතාලියේ 'ග්‍රොටා ඩෙල් රොමානෙලි' හා ශ්‍රී ලංකාවේ 'තන්තිරිමලේ' චිත්‍ර අතර පොදු වන්නේ කුමන ශෛලිමය ලක්ෂණයද?", "රේඛාමය හා සරල ජ්‍යාමිතික ස්වරූපය", "පුනරුද ත්‍රිමාණ ස්ෆුමාටෝ ආලේපය", "බැරොක් ආලෝක අඳුරු තීව්‍රතාව", "චීන සේද පටියක ඇඳි ජල සායම්", "ලෝකයේ බොහෝ ප්‍රදේශවල පසුකාලීන ගුහා චිත්‍ර සරල රේඛීය හා ජ්‍යාමිතික හැඩයකට පරිවර්තනය විය."),
        q("ප්‍රාග් ඓතිහාසික කලා ඉතිහාසයේ 'පුරාණ විද්‍යාත්මක අගය' රැකගැනීම සඳහා ගුහා අනුරූ (Replicas) තැනූ රටක් වන්නේ කුමක්ද?", "ප්‍රංශය (ලැස්කෝ II සහ ෂෝවේ II)", "මහා බ්‍රිතාන්‍යය (ලන්ඩන් පාලම)", "ඊජිප්තුව (අබු සිම්බල්)", "ජපානය (කියෝතෝ මාලිගය)", "මුල් ගුහා විනාශ වීම වැළැක්වීමට ප්‍රංශයේ ලැස්කෝ හා ෂෝවේ ගුහාවල පූර්ණ ප්‍රමාණයේ අනුරූ ඉදිකර ඇත."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික කලාව පිළිබඳව හැදෑරීමේදී 'මකුළු මැටි' යනු කුමක්ද?", "වර්ණ සෑදීමට යොදා ගත් ස්වභාවික සුදු මැටි විශේෂයකි", "වහලයේ ඇති මකුළු දැල් එකතු කර සෑදූ දියරයකි", "කළු පැහැති ගල් අඟුරු කුඩු විශේෂයකි", "මුහුදු බෙල්ලන් පුළුස්සා ගන්නා අළු වර්ගයකි", "සුදු මකුළු මැටි (Kaolin) ආදි ගුහා චිත්‍රවල සිට මහනුවර බිතුසිතුවම් දක්වා සුදු වර්ණකය ලෙස යොදා ගැනිණි."),
        q("ආදි ගුහා කලාවේදී චිත්‍ර ඇඳි පුද්ගලයා තුළ 'දෘශ්‍ය මතකය' (Visual Memory) ඉතා ප්‍රබලව පැවති බව තහවුරු වන්නේ කෙසේද?", "අඳුරු ගුහා තුළදී සතුන් නොබලාම නිවැරදිව චලන ඇඳීමෙන්", "සෑම චිත්‍රයකම සත්වයාගේ නම ලියා තැබීමෙන්", "කැමරා ඡායාරූප බලාගෙන කැටයම් කිරීමෙන්", "දිවා කාලයේ එළිමහනේ තබා ඇඳීමෙන්", "සැතපුම් ගණනක් ඈත තණබිම්වල දුටු සතුන්ගේ නිවැරදි ඉරියව් අඳුරු ගුහා ඇතුළත මතකයෙන් ඇඳ ඇත."),
        q("අනුරාධපුර ඇතුළු නුවර කැණීම්වලින් හමුවූ ක්‍රි.පූ. යුගයට අයත් මැටි බඳුන් කැබලි මත කොටා තිබූ සුවිශේෂී ලකුණු මොනවාද?", "ප්‍රාග්-බ්‍රාහ්මී අක්ෂර හා සංකේත සටහන්", "ඉංග්‍රීසි හෝඩියේ ප්‍රධාන අකුරු", "ලන්දේසි නැගෙනහිර ඉන්දීය සමාගම් මුද්‍රා", "නූතන ගණිත කුලක සංකේත", "කාලරක්ත මැටි බඳුන් මත කෙටූ මෙම සංකේත ලංකාවේ අක්ෂර කලාවේ ආදිතම සාධක වේ."),
        q("ප්‍රාග් ඓතිහාසික මූර්තියක් වන 'ටුක් ඩි ඔඩෝබර්ට්' බයිසන් රූප නිමවා ඇත්තේ කුමන ක්‍රමයකටද?", "පොළොවෙන් ගත් තෙත් මැටි ගල මත අඹා උන්නත කිරීමෙන්", "ග්‍රැනයිට් කළුගල පුපුරුවා හැරීමෙන්", "ලී කඳන් කපා ඉහළින් එල්ලීමෙන්", "තඹ තහඩු මිටියෙන් තලා හැඩ ගැන්වීමෙන්", "උන්නත මැටි මූර්ති (Clay Relief) ලෙස ගුහාවේ ගල් ආධාරකයට හේත්තු කර අඹා ඇත."),
        q("ස්පාඤ්ඤයේ 'ලා පිලේටා' ගුහාවේ හමුවන මත්ස්‍ය රූපයක ඇති කලාත්මක විශේෂත්වය කුමක්ද?", "සත්වයාගේ රූපය තුළ පිළිසිඳුණු පැටවුන් හෝ අභ්‍යන්තර අවයව දැක්වීම", "මසුන් රන් පැහැයෙන් ඔප දමා තිබීම", "මසුන්ට මිනිස් අත් පා ඇඳ තිබීම", "මසුන් සමූහයක් වෘත්තාකාරව නැටීම", "අනෙකුත් ගුහා සත්ව රූප මෙන් මෙහිද ජීවීන්ගේ වැඩීම හා ආහාර සුලබතාව හඟවන රූප වේ."),
        q("නවශිලා යුගයේ 'විවීමේ කලාව' (Weaving) බිහිවීම චිත්‍ර කලාවේ කුමන අංශයට පසුබිම් වීද?", "සමමිතික රටා හා පැදුරු මෝස්තර නිර්මාණයට", "තෙල් සායම් සඳහා වානේ තහඩු සැකසීමට", "දිය යට කිමිදුම් ඇඳුම් මැසීමට", "ශබ්ද පටිගත කිරීමේ පටි තැනීමට", "පන් හා කෙඳි විවීමේදී ඇති වන කොටු රටා (Grid patterns) මැටි බඳුන් හා මෝස්තර කලාවට බලපෑවේය."),
        q("ලංකාවේ වියළි කලාපීය ආදි චිත්‍ර හා ඉන්දියාවේ මධ්‍යශිලා චිත්‍ර අතර පවතින ප්‍රධාන සමානකම කුමක්ද?", "සරල රේඛීය මිනිස් රූප හා දඩයම් දර්ශන නිරූපණය", "සම්පූර්ණ වීදුරු මොසැයික් භාවිතය", "චීන පිඟන් මැටි භාවිතය", "ත්‍රිමාණ ග්‍රීක පිළිම සැලසුම්", "ඉන්දියාවේ භිම්බෙට්කා මධ්‍යශිලා චිත්‍ර හා ලංකාවේ ආදි ලෙන් චිත්‍ර සරල රේඛීය ශෛලියෙන් සමාන වේ."),
        q("ආදි ගුහා සිතුවම්කරුවා 'පින්තාරු කිරීමට පෙර ගල මතුපිට සූරා පිරිසිදු කර ඇති බව' පෙනී යන්නේ කුමකින්ද?", "වර්ණ යටින් තියුණු ගල් සීරුම් රේඛා හමු වීමෙන්", "සබන් පෙණ තට්ටු ඉතිරි වී තිබීමෙන්", "වැලි කඩදාසි කැබලි බිම වැටී තිබීමෙන්", "කෘත්‍රිම ප්ලාස්ටර් තට්ටු දමා තිබීමෙන්", "වර්ණ ආලේප කිරීමට පෙර දළ සැකිල්ල කොටා ගැනීම හා පෘෂ්ඨය සූරා ගැනීම සිදු කර ඇත."),
        q("ඉතාලියේ 'ග්‍රොටා ඩි ජෙනෝවේසි' ගුහාවේ ඇති කළු රේඛා චිත්‍ර අතර ප්‍රධාන වශයෙන් දක්නට ලැබෙන තේමාව කුමක්ද?", "ටූනා මසුන් හා මිනිස් රූප සහිත චාරිත්‍රමය දර්ශන", "මහනුවර පෙරහැරේ නැට්ටුවන්", "ඊජිප්තු පාරාවෝවරුන්ගේ යුද රථ", "රෝම සෙනෙට් සභා රැස්වීම්", "මධ්‍යධරණී දූපතක් වන ලෙවන්සෝහි මෙම ගුහාවේ මුහුදු මසුන් හා සරල මිනිස් රූප හමුවේ."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික මානවයා 'කහඳ' (Quartz) හා 'චර්ට්' (Chert) ගල් යොදා ගත්තේ කුමන කාර්යයකටද?", "කුඩා ජ්‍යාමිතික ගල් ආයුධ (Microliths) සෑදීමට", "රන් කැටයම් ඔප දැමීමට", "තෙල් සායම් සෑදීමට කුඩු කිරීමට", "විශාල පන්සල් බිත්ති බැඳීමට", "තියුණු දාර සහිත කුඩා ගල් ආයුධ සෑදීමට පිරිසිදු කහඳ සහ චර්ට් ගල් බහුලව යොදා ගැණිනි."),
        q("පුරාශිලා ගුහා චිත්‍රවල 'ඉහළ වහලයේ' චිත්‍ර ඇඳීම සඳහා ආදි ශිල්පීන් යොදා ගන්නට ඇතැයි සැලකෙන ක්‍රමය කුමක්ද?", "දැව කඳන්වලින් තාවකාලික පලංචි (Scaffolding) සෑදීම", "රබර් ඉණිමං භාවිත කිරීම", "වතුරෙන් ගුහාව පුරවා ඔරුවකින් ඇඳීම", "වර්ණ ඉහළට විසි කර රූප සෑදීම", "ලැස්කෝ ගුහාවේ බිත්තිවල පලංචි ලී කඳන් සවි කළ කුහර සලකුණු පුරාවිද්‍යාඥයන් සොයාගෙන ඇත."),
        q("ලෝකයේ 'ප්‍රාග් ඓතිහාසික කලා උරුමය' පිළිබඳ O/L චිත්‍ර කලා සිසුවෙකු උගත යුතු ප්‍රධාන පාඩම කුමක්ද?", "සීමිත ස්වභාවික සම්පත්වලින් උසස් ප්‍රකාශන ශක්තියක් මතු කළ හැකි බව", "මිල අධික කෘත්‍රිම වර්ණ නොමැතිව චිත්‍ර ඇඳිය නොහැකි බව", "සිතුවම් ඇඳීමට සෑම විටම පාසල් උපකරණ අවශ්‍ය බව", "ගුහා චිත්‍රවල කිසිදු රේඛා කුසලතාවක් නොමැති බව", "වර්ණ තුනකින් හා රළු බිත්තියකින් වුවද ජීවමාන හැඟීම් ප්‍රකාශ කළ හැකි බව මෙයින් උගත හැක."),
        q("ප්‍රංශයේ 'රොක් ඕ සෝසියර්ස්' (Roc-aux-Sorciers) හි විශේෂත්වය කුමක්ද?", "පර්වතයේ කැටයම් කළ ස්වභාවික ප්‍රමාණයේ අශ්ව හා කාන්තා උන්නත කැටයම්", "තෙල් සායමින් ඇඳි නාවික සිතියම්", "මැටියෙන් තැනූ කුඩා නැව් ආකෘති", "රන් තහඩු මත ඇඳි වීනස් රූප", "පුරාශිලා යුගයේ ශිලා උන්නත කැටයම් (Bas-relief) කලාවේ විශිෂ්ටතම උදාහරණයක් මෙහි ඇත."),
        q("ශ්‍රී ලංකාවේ 'පූනෑව' හා 'මාරවිල' වැනි ප්‍රදේශවලින් හමුවන මහාශිලා මැටි බඳුන්වල දක්නට ලැබෙන කලාත්මක හැඩතල මොනවාද?", "සියුම් ලෙස හැඩ ගැන්වූ පාදම් සහිත කළ, හට්ටි සහ පාත්‍ර", "චතුරස්‍රාකාර තේ කෝප්ප සහ පීරිසි", "වීදුරු කැටයම් කළ මල් බඳුන්", "කැටයම් කළ පෝසිලේන් පිළිම", "උසස් තාක්ෂණයකින් සෑදූ විවිධ ප්‍රමාණයේ මැටි පාත්‍ර හා සුසාන බඳුන් මෙහිදී හමුවේ."),
        q("ආදි ගුහා සිතුවම්වල බොහෝ සතුන් 'ගැබ්බර' හෝ සශ්‍රීක ස්වරූපයෙන් ඇඳීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?", "සත්ව ගහනය වර්ධනය වී ආහාර සුලබ වීම ප්‍රාර්ථනා කිරීම", "සතුන් රෝගාතුර වූ බව පෙන්වීම", "කලාකරුවන්ට සිහින් රේඛා ඇඳීමට නොහැකි වීම", "සතුන්ගේ සිරුරු ඉදිමී ඇති බව දැක්වීම", "වන සතුන් බෝ වී දඩයම සරු වේවා යන සශ්‍රීකත්ව අභිචාරය මෙයින් පිළිබිඹු වේ."),
        q("ප්‍රංශයේ 'ට්‍රොයිස් ෆ්‍රේරෙස්' ගුහාවේ 'හොරණෑ හෝ දුනු' ගත් රූපයක් ලෙස විචාරකයන් හඳුන්වන චිත්‍රයෙන් ඉඟි කෙරෙන්නේ කුමක්ද?", "ආදි අභිචාර සමඟ සංගීතය හා නර්තනය බැඳී පැවති බව", "පැරණි යුද හමුදා පෙළපාලි පැවැත්වූ බව", "රජ මාලිගාවේ කවිකාර මඩුව පැවති බව", "බටහිර සම්භාව්‍ය සංගීත ප්‍රසංග පැවති බව", "බයිසන් රංචුවක් පිටුපස සංගීත දුන්නක් වයන අර්ධ මිනිස් රුව සංගීතයේ හා කලාවේ බැඳීම දක්වයි."),
        q("ශ්‍රී ලංකාවේ 'ගල්ලෑන්තැන්න' සහ 'මහවැලි' නිම්නයේ ප්‍රාග් ඓතිහාසික සාක්ෂිවල වැදගත්කම කුමක්ද?", "ගංගා ආශ්‍රිතව ආදි මානව කලා හා මෙවලම් ව්‍යාප්තිය පෙන්වීම", "රෝම අධිරාජ්‍යයේ බලකොටු තිබූ බව පෙන්වීම", "මුහුදු යාත්‍රා තැනූ බව පෙන්වීම", "චීන සේද මාවත පැවති බව පෙන්වීම", "ප්‍රධාන ගංගා නිම්න ආශ්‍රිතව ජලය හා දඩයම් නිසා ආදි මානව ජනාවාස හා කලා බිහිවිය."),
        q("ප්‍රාග් ඓතිහාසික චිත්‍රවල 'අභ්‍යන්තර වර්ණ පිරවීමේදී' (Shading) ආදි ශිල්පියා සිදු කළ දක්ෂ ක්‍රියාව කුමක්ද?", "තද පැහැයේ සිට ලා පැහැයට වර්ණ ශ්‍රේණිගත කිරීම", "එකම තනි තීන්ත තට්ටුවක් ඝනට ඇතිරීම", "කොටු දැලක් ගසා සෑම කොටුවක්ම පිරවීම", "පැන්සලෙන් ඉරි ගසා ඡායා දැක්වීම", "අඟුරු හා ගුරුගල් අතේ හෝ සම් කැබැල්ලක අතුල්ලා සත්වයාගේ බඩ හා පිට ප්‍රදේශයේ ත්‍රිමාණ බව මතු කළේය."),
        q("ලංකාවේ 'බුදුගල' ගුහා සිතුවම් අයත් වන්නේ කුමන ප්‍රදේශයටද?", "අම්පාර හා බින්තැන්න කලාපයට", "කළුතර හා ගාල්ල කලාපයට", "මාතලේ හා නුවරඑළිය කලාපයට", "යාපනය හා මන්නාරම කලාපයට", "නැගෙනහිර පළාතේ ගල් ලෙන්වල වැදි ජනතාවගේ ආදි චිත්‍ර කැපී පෙනෙන ලෙස හමුවේ."),
        q("නවශිලා යුගයේ 'වර්ණ ගැන්වූ මැටි බඳුන්' (Painted Pottery) ප්‍රථමයෙන් උසස් මට්ටමකට පැමිණියේ කුමන කලාපයේද?", "මැදපෙරදිග, මෙසපොතේමියාව සහ ඉන්දු නිම්නය", "ඇන්ටාක්ටිකාව සහ ග්‍රීන්ලන්තය", "සයිබීරියාව සහ ඇලස්කාව", "හවායි සහ පොලිනීසියාව", "කෘෂිකාර්මික ශිෂ්ටාචාර ඇරඹුණු මෙසපොතේමියාව හා ඉන්දු නිම්නයේ වර්ණවත් මැටි බඳුන් විශිෂ්ට ලෙස දියුණු විය."),
        q("ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර අධ්‍යයනයේදී 'නියැන්ඩතාල් මානවයාට' පවා කලා හැකියාව තිබූ බව සනාථ වී ඇති සාක්ෂිය කුමක්ද?", "වසර 64,000ක් පැරණි ස්පාඤ්ඤ ගුහා රතු සංකේත", "රෝම කොලෝසියමේ මූර්ති නිර්මාණ", "සීගිරි කැටපත් පවුරේ කවි", "අජන්තා බිතුසිතුවම් මාලාව", "හෝමෝ සේපියන්වරුන් යුරෝපයට ඒමට පෙර ඇඳි රතු පැහැ ඉණිමඟ හැඩතල නියැන්ඩතාල් නිර්මාණ ලෙස සැලකේ."),
        q("ආදි ගුහා සිතුවම්වල 'සත්ව රූප' සමඟ නිතර දක්නට ලැබෙන 'කුඩා රේඛා කණ්ඩායම්' කුමක් සඳහා යොදා ගන්නට ඇතැයි සැලකේද?", "ගණන් කිරීමේ හෝ කාල සටහන් සංකේත ලෙස", "මිල ගණන් දැක්වෙන ලේබල් ලෙස", "වීදුරු ජනෙල් රාමු ලෙස", "රෙදි මැසීමේ මැහුම් රටා ලෙස", "තිත් හා ඉරි පේළි චන්ද්‍ර මාස හෝ සත්ව ගහන ගණනයන් දක්වන සටහන් ලෙස සැලකේ."),
        q("ශ්‍රී ලංකාවේ 'අලුත්නුවර' හා 'හේනන්නේගල' වැනි ස්ථානවල ආදි ලෙන් චිත්‍රවල වැඩි වශයෙන් නිරූපණය කර ඇති මිනිස් ක්‍රියාකාරකම කුමක්ද?", "සතුන් පසුපස හඹා යාම හා දඩයම් කිරීම", "පන්සල් තැනීම හා පින්කම් කිරීම", "වෙළඳසැල් පවත්වාගෙන යාම", "ගුවන් යානා පැදවීම", "වැදි සමාජයේ ජීවන රටාව වූ දුන්නෙන් විදීම හා මී කැඩීම වැනි දර්ශන එහි ඇඳ ඇත."),
        q("පුරාශිලා ගුහා චිත්‍රවල ඇඳ ඇති සමහර සතුන්ට 'මුහුණු හෝ පාද අසම්පූර්ණව' තිබීමෙන් කලා විචාරකයන් දකින්නේ කුමක්ද?", "කලාකරුවාට හෝ ප්‍රේක්ෂකයාට අනවශ්‍ය කොටස් අත්හැරීමේ හැකියාව", "වර්ණක ඉවර වීම නිසා නැවැත්වීම", "පර්වතය කැඩී යාමෙන් අතුරුදන් වීම", "කලාකරුවන් නිදාගෙන ඇඳීම", "වැදගත්ම චලනය හෝ ලක්ෂණය පමණක් රේඛාවකින් දක්වා ඉතිරිය පරිකල්පනයට ඉඩ හැරීම මෙහි ලක්ෂණයකි."),
        q("ලොව පැරණිතම සත්ව රූප චිත්‍ර හමු වී ඇති ඉන්දුනීසියාවේ 'ලියං ටෙඩොංගේ' (Leang Tedongnge) ගුහාවේ ඇඳ ඇති සත්වයා කවුද?", "සුලවේසි වල් ඌරා", "අප්‍රිකානු සිංහයා", "ධ්‍රැව වලසා", "ඕස්ට්‍රේලියානු කැන්ගරුවා", "වසර 45,500ක් පැරණි රතු ගුරුගල්වලින් ඇඳි වල් ඌරු රූපයක් එම ගුහාවෙන් සොයාගෙන ඇත."),
        q("දොරවක කන්ද ලෙන් කැටයම් මතුපිට ඇති 'සුර්යයා' වැනි රවුම් හැඩය හා එළියට විහිදෙන රේඛා කුමක් සංකේතවත් කරයිද?", "ආලෝකය, ශක්තිය හා ජීවයේ පැවැත්ම", "කාර් රෝදයක් හා ටයරයක්", "නූතන ඔරලෝසු මුහුණතක්", "පිඟන් කෝප්ප සැලසුමක්", "ආදි ශිෂ්ටාචාරවල සූර්ය වන්දනය හා ස්වාභාවික ශක්ති සංකේත ලෙස එම රටා යොදා ගැනිණි."),
        q("නවශිලා යුගයේ මැටි මූර්ති නිර්මාණයේදී මැටි පිපිරීම වැළැක්වීම සඳහා මැටියට මිශ්‍ර කළ ස්වභාවික ද්‍රව්‍ය මොනවාද?", "සියුම් වැලි, සිප්පි කටු කුඩු හෝ පිදුරු", "සිමෙන්ති සහ කෘත්‍රිම ග්ලූ", "රබර් කිරි සහ පෙට්‍රල්", "රසදිය සහ යකඩ ඇණ", "මැටි පිළිස්සීමේදී හැකිළී පුපුරා යාම වැළැක්වීමට වැලි හෝ ශාක කෙඳි (Temper) මිශ්‍ර කෙරිණි."),
        q("ප්‍රාග් ඓතිහාසික කලා නිර්මාණවල 'පෞද්ගලික අත්සනක්' (Signature) දක්නට නොලැබෙන්නේ ඇයි?", "කලාව පෞද්ගලික කීර්තිය වෙනුවට සාමූහික අභිචාරයක් වූ බැවින්", "කලාකරුවන්ට තමන්ගේ නම් නොතිබූ බැවින්", "අත්සන් යෙදීමට කඩදාසි නොතිබූ බැවින්", "නීතියෙන් කලාකරුවන් සැඟවී සිටි බැවින්", "සමස්ත ගෝත්‍රයේම යහපත උදෙසා සිදු කළ සාමූහික පූජනීය ක්‍රියාවක් වූ නිසා පෞද්ගලික නම් යෙදුවේ නැත."),
        q("ශ්‍රී ලංකාවේ 'තන්තිරිමලේ' හා 'දොරවක කන්ද' ආදි කලා උරුමයන් ආරක්ෂා කිරීම පවරා ඇති රාජ්‍ය ආයතනය කුමක්ද?", "පුරාවිද්‍යා දෙපාර්තමේන්තුව", "වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව පමණි", "රේගු දෙපාර්තමේන්තුව", "කාලගුණ විද්‍යා දෙපාර්තමේන්තුව", "1940 පුරාවිද්‍යා ආඥා පනත යටතේ සියලු පෞරාණික ලෙන් සිතුවම් හා ස්මාරක පුරාවිද්‍යා දෙපාර්තමේන්තුව මගින් සුරැකේ."),
        q("පුරාශිලා ගුහා සිතුවම්කරණයේදී 'පෙනුම පමණක් නොව ධ්වනියද' (Acoustics) වැදගත් වූ බව විද්වතුන් පවසන්නේ ඇයි?", "දෝංකාරය වැඩි ගුහා කුටීරවල වැඩිම සිතුවම් ඇඳ තිබීමෙන්", "ගුහා බිත්ති මත සංගීත ස්වර ප්‍රස්තාර ලියා තිබීමෙන්", "ගුහා තුළ වීණා සහ පියානෝ හමු වීමෙන්", "සිතුවම්වල කන් වසාගත් මිනිසුන් ඇඳ තිබීමෙන්", "ශබ්දය හොඳින් දෝංකාර දෙන ගුහා කුටීර අභිචාරමය නැටුම් හා සිතුවම් සඳහා තෝරාගෙන ඇති බව පෙනේ."),
        q("ලංකාවේ ආදි වැදි ජනතාව ගල් ලෙන්වල ඇඳි 'කෙම්' හෝ 'මී වද' රූපවලින් පිළිබිඹු වන්නේ කුමක්ද?", "මී පැණි එකතු කිරීමේ ආර්ථික හා සංස්කෘතික වැදගත්කම", "රජ මාලිගාවේ කැවිලි සෑදීමේ ක්‍රමය", "බටහිර කෘෂිකාර්මික සැලැස්ම", "නූතන වෙළඳ දැන්වීම් රටාව", "පැණි රැස් කිරීම වැදි සමාජයේ ප්‍රධාන ආහාර සංස්කෘතියක් වූ අතර එය ලෙන් චිත්‍රවල නිරූපණය විය."),
        q("ඕස්ට්‍රේලියාවේ 'කකඩු' (Kakadu) ජාතික වනෝද්‍යානයේ ගල් ලෙන් චිත්‍රවල විශේෂත්වය කුමක්ද?", "වසර 20,000කට අධික කාලයක් අඛණ්ඩව ඇඳි සිතුවම් පැවතීම", "වර්ණ කිසිවක් නොමැතිව ගල් පමණක් තැබීම", "පුනරුද යුගයේ චිත්‍ර එහි පිටපත් කිරීම", "චීන අධිරාජ්‍යයන්ගේ ප්‍රතිමා නෙළීම", "ලොව දීර්ඝතම අඛණ්ඩ ආදිවාසී ගල් චිත්‍ර සම්ප්‍රදායන්ගෙන් එකක් කකඩු ලෙන්වල දක්නට ලැබේ."),
        q("නවශිලා යුගයේ 'පොළොන්නරු හා අනුරාධපුර' පූර්ව ජනාවාස කලාවේදී ලෝහ භාවිතය ඇරඹීමට පෙර භාවිත කළ මැටි බඳුන් නිමාව කුමක්ද?", "ගලකින් මැටි බඳුන් පෘෂ්ඨය අතුල්ලා ඔප දැමීම", "සින්තටික් ලැකර් ඉස දිලිසීම", "කෘත්‍රිම ඉනැමල් උදුනේ පිළිස්සීම", "රසදිය තට්ටුවක ගිල්වීම", "පිළිස්සීමට පෙර සිනිඳු ගඟේ ගලකින් අතුල්ලා මැටි බඳුන් ඔප දැමීම (Burnishing) සිදු කෙරිණි."),
        q("ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර නිර්මාණයේදී 'පහසුවෙන් ළඟා විය නොහැකි ඉහළ ස්ථානවල' ඇඳ තිබීමෙන් කුමක් පෙන්නුම් කෙරේද?", "කලාව කෙරෙහි තිබූ දැඩි කැපවීම හා පූජනීය ගෞරවය", "මිනිසුන්ට පියාඹා යාමේ හැකියාව තිබූ බව", "ගුහාව පසුව පොළොවට ගිලා බැස්ස බව", "වඳුරන් විසින් චිත්‍ර ඇඳ ඇති බව", "පටු හා අඳුරු තැන් කරා දැඩි වෙහෙසකින් ගොස් චිත්‍ර ඇඳීම ඒවායේ ශුද්ධ අගය තහවුරු කරයි."),
        q("ලෝකයේ ආදි ගුහා සිතුවම් හා ලංකාවේ ආදි ගුහා සිතුවම් 'වර්ණ විවිධත්වය' අතින් සැසඳීමේදී නිවැරදි කරුණ කුමක්ද?", "යුරෝපීය ගුහාවල බහුවර්ණ සෙවණැලි වැඩි අතර ලංකාවේ රේඛා සරල බව වැඩිය", "ලංකාවේ ගුහාවල තෙල් සායම් වැඩි අතර යුරෝපයේ අඟුරු පමණි", "දෙකෙහිම කෘත්‍රිම ප්ලාස්ටික් වර්ණ යොදා ඇත", "ලංකාවේ කිසිදු ගුහා චිත්‍රයක් හමුවී නැත", "ඇල්ටමීරා වැනි ගුහාවල බහුවර්ණ ත්‍රිමාණ බව වැඩි අතර ලංකාවේ ලෙන් චිත්‍ර සරල රේඛීය ස්වභාවයක් ගනී."),
        q("ප්‍රාග් ඓතිහාසික ශිල්පියා විසින් 'බිත්තියක පැල්මක් හෝ ගැටියක්' කඳු මුදුනක් හෝ සත්ව කොටසක් ලෙස භාවිත කිරීම හඳුන්වන්නේ කුමන හැකියාවක් ලෙසද?", "ස්වභාවික පරිසර ලක්ෂණ නිර්මාණාත්මකව යොදාගැනීම", "පර්වතය කඩා දැමීමේ දුර්වලතාව", "වර්ණ නාස්ති කිරීමේ පුරුද්ද", "සත්ව විද්‍යාත්මක අසමත්භාවය", "ගලේ ස්වභාවික හැඩය දෙස බලා සත්වයාගේ රුව ඒ මත මතු කිරීම ඉහළ පරිකල්පන හැකියාවකි."),
        q("පුරාණ ලංකාවේ 'ආදි චිත්‍ර කලාව' පිළිබඳ හැදෑරීමේදී තන්තිරිමලේ රේඛා සිතුවම් මූලිකවම අයත් වන්නේ කුමන ශෛලියටද?", "ප්‍රාථමික සංකේතාත්මක රේඛා ශෛලියට", "සම්භාව්‍ය ත්‍රිමාණ සීගිරි ශෛලියට", "බටහිර යථාර්ථවාදී ශෛලියට", "ජපන් උකියෝ-ඉ ශෛලියට", "තන්තිරිමලේ බිල්ලෑව ලෙන් චිත්‍ර සංකේතාත්මක රේඛා හා සරල හැඩතලවලින් සමන්විත වේ."),
        q("ප්‍රාග් ඓතිහාසික ගුහා කලා යුගය අවසන් වී ශිෂ්ටාචාරගත චිත්‍ර කලාව ආරම්භ වීමට බලපෑ ප්‍රධාන ඓතිහාසික සංසිද්ධිය කුමක්ද?", "නගර රාජ්‍ය, කෘෂිකර්මාන්තය හා ලේඛන කලාව බිහිවීම", "ලෝකයේ සියලු ගුහා මුහුදට යටවීම", "සතුන් සියල්ල වඳ වී යාම", "කඩදාසි මුද්‍රණ යන්ත්‍ර නිපදවීම", "මෙසපොතේමියාව හා මිසරය වැනි ගංගා නිම්න ශිෂ්ටාචාර ඇරඹීමත් සමඟ දේවාල හා රාජ කලා බිහිවිය."),
        q("ආදි ගුහා සිතුවම්වල දක්නට ලැබෙන 'කළු, රතු, කහ සහ සුදු' වර්ණ සමූහය කලා ඉතිහාසයේ හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "ආදි පෘථිවි වර්ණ පුවරුව (Earth Palette)", "නූතන නියෝන් වර්ණ පුවරුව", "කෘත්‍රිම රසායනික වර්ණ මාලාව", "ජල සායම් විනිවිද පුවරුව", "පොළොවෙන් ස්වභාවිකව ලැබෙන ගුරුගල්, මැටි හා අඟුරු වර්ණ සමූහය පෘථිවි වර්ණ ලෙස හැඳින්වේ."),
        q("පුරාශිලා ගුහා චිත්‍ර කලාවේ 'මාංශපේශී හා සන්ධි' ඉතා නිවැරදිව දැක්වීමට ආදි මිනිසාට හැකි වූයේ කෙසේද?", "දඩයම් කළ සතුන් සමීපව නිරීක්ෂණය කිරීම හා කැපීම නිසා", "කායව්‍යවච්ඡේද විද්‍යා පොත් කියවීම නිසා", "වෛද්‍ය විද්‍යාලවල පුහුණුව ලැබූ නිසා", "ඡායාරූප කැමරා භාවිත කළ නිසා", "එදිනෙදා දඩයමේදී සතුන්ගේ චලනය හා ශරීර සැකැස්ම සියුම්ව නිරීක්ෂණය කිරීම ඊට හේතු විය."),
        q("දොරවක කන්ද ගුහා කැටයම් හා අනුරාධපුර කැටයම් අතර සංසන්දනයේදී වැදගත් වෙනසක් වන්නේ කුමක්ද?", "දොරවක කන්ද කෙටුම් කිසිදු උපකරණ තාක්ෂණික ඔප දැමීමකින් තොර ප්‍රාථමික කෙටුම් වීම", "දොරවක කන්ද කැටයම් කිරිගරුඬ ගලෙන් නිමවා තිබීම", "අනුරාධපුර කැටයම් ඇඟිලිවලින් පමණක් ඇඳ තිබීම", "දෙකම බ්‍රිතාන්‍ය පාලන සමයේ නිර්මාණ වීම", "ප්‍රාග් ඓතිහාසික කෙටුම් ප්‍රාථමික රේඛා කෙටුම් වන අතර අනුරාධපුර කැටයම් දියුණු ශිල්පීය නිර්මාණ වේ."),
        q("ප්‍රාග් ඓතිහාසික ගුහා සිතුවම් 'ලෝක කලා ඉතිහාසයේ' පළමු පරිච්ඡේදය ලෙස සෑම රටකම උගන්වන්නේ ඇයි?", "මානව සංස්කෘතික විවිධත්වය තුළ ඇති පොදු නිර්මාණශීලී මූලය පෙන්වන බැවින්", "සියලුම ගුහා එකම රටක පිහිටා ඇති බැවින්", "විභාග ප්‍රශ්න පත්‍ර පහසු කිරීම සඳහා පමණි", "එම යුගයේ චිත්‍ර පමණක් වර්ණවත් වන බැවින්", "මිනිසා කලාකරුවෙකු ලෙස පළමු වරට සිය ලෝකය සිතුවමට නැගුවේ ප්‍රාග් ඓතිහාසික ගුහා තුළදීය."),
        q("ශ්‍රී ලංකාවේ 'ලෙන් සිතුවම්' ආශ්‍රිතව අධ්‍යයනය කළ හැකි ආදිවාසී සංස්කෘතික අංගය කුමක්ද?", "සොබාදහම සමඟ ගැටෙමින් ජීවත් වූ සරල දඩයම් දිවිය", "විශාල නගර පාලනය හා අධිරාජ්‍ය ගොඩනැගීම", "රන් හා රිදී කර්මාන්තශාලා පාලනය", "මුහුදු යාත්‍රා මගින් වෙළඳ ගිවිසුම් ඇති කිරීම", "වැදි ජනතාවගේ ආදි ගුහා චිත්‍ර ඔවුන්ගේ දඩයම්, ආහාර හා පරිසර සබඳතාව පිළිබිඹු කරයි."),
        q("ගුහා සිතුවම්වල 'නෙගටිව් හස්ත සලකුණක්' (Negative Handprint) සහ 'පොසිටිව් හස්ත සලකුණක්' අතර වෙනස කුමක්ද?", "නෙගටිව් සලකුණේ වටේ වර්ණ ගන්වන අතර පොසිටිව් සලකුණේ අතේ වර්ණ ගා ඔබයි", "නෙගටිව් සලකුණ කළු පැහැති වන අතර පොසිටිව් සලකුණ නිල් පැහැති වේ", "නෙගටිව් සලකුණ පාදයෙන් තබන අතර පොසිටිව් සලකුණ අතින් තබයි", "දෙක අතර කිසිදු වෙනසක් නොමැත", "වර්ණ පිඹ අත ඉවත් කිරීම නෙගටිව් ක්‍රමය වන අතර අතේ තීන්ත ගා තැබීම පොසිටිව් ක්‍රමයයි."),
        q("ලෝක ප්‍රකට 'විලෙන්ඩෝෆ්හි වීනස්' ප්‍රතිමාවේ සැබෑ උස කොපමණ වේද?", "සෙන්ටිමීටර 11ක් පමණ කුඩා ප්‍රමාණයකි", "මීටර් 3ක් පමණ විශාල ප්‍රමාණයකි", "මීටර් 10ක් පමණ දැවැන්ත ප්‍රමාණයකි", "සෙන්ටිමීටර 150ක් පමණ උස ප්‍රමාණයකි", "අතේ ගෙන යා හැකි සෙන්ටිමීටර 11.1ක් උස කුඩා හුණුගල් ප්‍රතිමාවක් වීම මෙහි විශේෂත්වයකි."),
        q("ප්‍රාග් ඓතිහාසික මූර්ති කලාවේ 'උන්නත කැටයම්' (Relief) සහ 'පූර්ණ වටකුරු මූර්ති' (In-the-round) යන දෙවර්ගයම බිහි වූයේ කවදාද?", "පසු පුරාශිලා යුගයේදී", "නූතන කාර්මික යුගයේදී", "කෝට්ටේ රාජධානි සමයේදී", "වික්ටෝරියානු යුගයේදී", "විලෙන්ඩෝෆ් වැනි වටකුරු මූර්ති මෙන්ම පර්වත බිත්තිවල උන්නත කැටයම්ද පුරාශිලා යුගයේදී නිමැවිණි."),
        q("ශ්‍රී ලංකාවේ 'හේනන්නේගල' ලෙන් චිත්‍ර කැපී පෙනෙන්නේ කුමන කරුණක් නිසාද?", "ලෙන් වහලයේ අළු හා මැටියෙන් ඇඳි මිනිස් හා සත්ව සමූහ රූප නිසා", "රත්රන් ආලේපිත ලී කැටයම් තිබීම නිසා", "ග්‍රීක කිරිගරුඬ කුළුණු පිහිටීම නිසා", "චීන සෙරමික් පිඟන් ඔබ්බවා තිබීම නිසා", "වැදි ජනතාව විසින් ලෙන් වහලයේ හා බිත්තියේ ඇඳි ආදි සිතුවම් ගණනාවක් මෙහි හමුවේ."),
        q("ආදි ගුහා සිතුවම් 'සජීවී සිනමාවක පූර්වගාමියා' ලෙස ඇතැම් විචාරකයන් හඳුන්වන්නේ ඇයි?", "පන්දම් එළිය සෙලවෙන විට රූප චලනය වන සේ පෙනෙන බැවින්", "ගුහා තුළ පැරණි ප්‍රොජෙක්ටර් යන්ත්‍ර හමුවූ බැවින්", "සෑම චිත්‍රයකම වීඩියෝ තැටි තිබූ බැවින්", "කලාකරුවන් විදුලි පහන් නිවා දැමූ බැවින්", "පර්වතයේ වක්‍ර මත බහු රේඛා රූප පන්දම් එළියේ සෙලවීමෙන් සතුන් දුවන මායාවක් මැවේ."),
        q("ප්‍රාග් ඓතිහාසික මිනිසා විසින් නිපදවූ 'මැටි බඳුන් අලංකරණයේ' මුල්ම ක්‍රමය ලෙස සැලකෙන්නේ කුමක්ද?", "නියපොත්තෙන්, කෝටු කැබැල්ලකින් හෝ බෙලි කටුවකින් රටා එබීම", "රසායනික වීදුරු තීන්ත මුද්‍රණය කිරීම", "ලේසර් කිරණවලින් රූප කැපීම", "මුද්‍රිත කඩදාසි මැටි මත ඇලවීම", "තෙත මැටි මතුපිට ඇඟිලිවලින් හෝ ගෙතූ කෙඳිවලින් ඔබා රටා මැවීම ආදි මැටි සැරසිලි ක්‍රමයයි."),
        q("ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික කලා උරුමය අධ්‍යයනය කිරීමෙන් මෙරට ඉතිහාසය ගැන තහවුරු වන වැදගත් සත්‍යය කුමක්ද?", "විජයාගමනයට බොහෝ පෙර සිටම දියුණු මානව සංස්කෘතියක් තිබූ බව", "ලංකාවේ මිනිසුන් කිසිදා ලෙන්වල ජීවත් නොවූ බව", "ලංකාවේ සියලු චිත්‍ර පසුගිය සියවසේ ඇඳි බව", "ආදි ලංකාවේ කිසිදු වන සතෙකු නොසිටි බව", "බලංගොඩ මානවයා ඇතුළු පූර්ව ඓතිහාසික ජනතාවට සිය සෞන්දර්ය හා සංකේත කලාවක් පැවති බව සනාථ වේ."),
        q("ස්පාඤ්ඤයේ 'මලැට්‍රැවියෙසෝ' (Maltravieso) ගුහාවේ වැඩි වශයෙන් සොයා ගෙන ඇති ආදි කලා සලකුණ මොනවාද?", "රතු වර්ණ පසුබිමේ ඇති හස්ත ස්ටෙන්සිල් සලකුණු", "ලෝකඩ අසිපත් කැටයම්", "පිළිස්සූ ගඩොල් මූර්ති", "රන්වන් මකර සිතුවම්", "මලැට්‍රැවියෙසෝ ගුහාවේ හැටකට අධික පැරණි අත් ස්ටෙන්සිල් සලකුණු දක්නට ලැබේ."),
        q("ප්‍රාග් ඓතිහාසික ගුහා සිතුවම්වල 'ප්‍රමාණයේ විශාලත්වය' (Scale) අනුව සැලකීමේදී ඇල්ටමීරාවේ බයිසන් රූප කෙබඳුද?", "සැබෑ සතුන්ට ආසන්න විශාල ප්‍රමාණවලින් ඇඳ ඇත", "කුඩා කෘමීන් තරම් ක්ෂුද්‍ර ලෙස ඇඳ ඇත", "මීටර් සියයක් තරම් විශාලව ඇඳ ඇත", "සියලු රූප අඟලක් තරම් කුඩාවට ඇඳ ඇත", "මීටර් 1.5 සිට මීටර් 2ක් පමණ දිගින් යුත් සැබෑ ප්‍රමාණයට ආසන්න රූප එහි ඇඳ තිබේ."),
        q("ආදි ගුහා කලාවේදී 'වැඩි වර්ණ ප්‍රමාණයක් නොමැති වීම' කලා කෘතියට බලපෑ ආකාරය කුමක්ද?", "රේඛාවේ ශක්තිය හා ආකෘතියේ සරල බව වඩාත් ඉස්මතු වීම", "කිසිදු සතෙකු හඳුනාගැනීමට නොහැකි වීම", "සිතුවම් සියල්ල වර්ෂාවට සේදී යාම", "චිත්‍රවල කිසිදු හැඟීමක් නොතිබීම", "සීමිත වර්ණ තුළ වුවද සියුම් රේඛා පාලනය නිසා ඉතා ප්‍රබල ප්‍රකාශනයක් ලැබී ඇත."),
        q("ශ්‍රී ලංකාවේ පැරණි ගුහා චිත්‍ර හඳුනාගැනීමට පර්යේෂණ කළ මහාචාර්ය සෝමදේව හා සිරාන් දැරණියගල වැනි විද්වතුන්ගේ දායකත්වය කුමක්ද?", "ප්‍රාග් ඓතිහාසික කාල නිර්ණ හා සංස්කෘතික ස්ථර තහවුරු කිරීම", "විහාරස්ථානවල නව ගොඩනැගිලි ඉදි කිරීම", "නූතන තෙල් සායම් චිත්‍ර ප්‍රදර්ශන පැවැත්වීම", "බටහිර මූර්ති ලංකාවට ආනයනය කිරීම", "විද්‍යාත්මක කැණීම් හා කාල නිර්ණ මගින් ලංකාවේ ආදි කලා හා මානව ඉතිහාසය තහවුරු කළහ."),
        q("පුරාශිලා යුගයේ සිට නවශිලා යුගය දක්වා මානව නිර්මාණශීලීත්වය වර්ධනය වීමෙන් පෙනී යන ප්‍රධාන සත්‍යය කුමක්ද?", "කලාව මානව ජීවන රටාව හා අවශ්‍යතා සමඟ සමගාමීව පරිණාමය වන බව", "කලාව යනු විනෝදාංශයක් පමණක් වන බව", "පැරණි මිනිසාට සෞන්දර්ය හැඟීමක් නොතිබූ බව", "කලාව ආරම්භ වූයේ කාර්මික විප්ලවයෙන් පසු බව", "දඩයමින් ගොවිතැනට මාරු වීමේදී චිත්‍ර හා කැටයම්ද ඊට අනුරූපව වෙනස් විය."),
        q("ආදි චිත්‍ර කලා ක්ෂේත්‍රයේ 'සත්ව අං හා අස්ථි මත කළ රේඛා කෙටුම්' (Engravings) සඳහා භාවිත කළ මෙවලම කුමක්ද?", "බියුරින් (Burin) නම් තියුණු ගල් කැටයම් තුඩ", "විදුලි කැපුම් යන්ත්‍ර", "වානේ පිරිසිදු කිරීමේ කියත", "ලෝහ පෑස්සුම් උපකරණය", "උල් තුඩක් සහිත 'බියුරින්' ගල් මෙවලම අස්ථි, ඇත්දත් හා ගල් කැටයම් කිරීමට යොදා ගති."),
        q("ශ්‍රී ලංකාවේ 'ගෝනවිල' හා 'ගමකන්ද' වැනි අඩවිවල වැදි ගුහා චිත්‍ර හඳුනාගැනීමේදී දැකිය හැකි පොදු තේමාව කුමක්ද?", "වන සතුන්, දඩයක්කරුවන් හා එදිනෙදා ක්‍රියාකාරකම්", "මුහුදු යාත්‍රා හා නාවික සිතියම්", "පන්සල් හා දේවාල ගොඩනැගිලි සැලසුම්", "යුද රථ හා අශ්වාරෝහක හමුදා", "වනාන්තර ජීවිතයට අදාළ සත්ව රූප හා දඩයම් අවස්ථා මෙම ගුහා චිත්‍රවල පොදු තේමාව විය."),
        q("ලෝකයේ ආදි ගුහා චිත්‍රවල 'ස්වභාවික භූ දර්ශන' වෙනුවට සතුන්ම මූලික වීමෙන් කුමන චින්තනයක් පැහැදිලි වේද?", "පැවැත්ම සඳහා වූ ආහාර හා ශක්තිය කෙරෙහි තිබූ ප්‍රධාන අවධානය", "ගස් වැල් නැති කාන්තාර පරිසරයක විසූ බව", "හරිත වර්ණය පිළිකුල් කළ බව", "සතුන්ට පමණක් ගුහාවලට ඇතුළු වීමට හැකි වූ බව", "ජීවත් වීම සඳහා දඩයම අත්‍යවශ්‍ය වූ හෙයින් සත්ව රූප මානව මනසේ ප්‍රධාන තැන ගත්තේය."),
        q("ප්‍රාග් ඓතිහාසික මූර්තියක් වන 'වීනස් ඔෆ් ලෙස්පුග්' (Venus of Lespugue) හි ඇති ජ්‍යාමිතික විශේෂත්වය කුමක්ද?", "සිරුරේ කොටස් ගෝලාකාර හා ඕවලාකාර ශෛලිගත හැඩතලවලින් නෙළා තිබීම", "ලෝකඩ තහඩු කපා එකට පාස්සා තිබීම", "මුළු රුවම චතුරස්‍ර කුට්ටියක් ලෙස තිබීම", "සිරුරේ තෙල් සායමින් මල් ඇඳ තිබීම", "ඇත්දත්වලින් නෙළූ මෙම රුවේ හැඩතල පසුකාලීන ඝනිකවාදී රූපවලට පවා ආභාසයක් වැනිය."),
        q("ශ්‍රී ලංකාවේ පූර්ව ඓතිහාසික කලා කෘති සංරක්ෂණයේදී 'ප්‍රදේශවාසීන් දැනුවත් කිරීම' අත්‍යවශ්‍ය වන්නේ ඇයි?", "නිදන් සෙවීම හා අනවසර කුරුටු ගෑම්වලින් පැරණි ලෙන් රැකගැනීමට", "ලෙන් තුළ නව හෝටල් ඉදිකිරීම සඳහා", "චිත්‍ර කැපුම් කැබලි විකුණා මුදල් සෙවීමට", "සියලු ගල් ලෙන් කළුගල් කොරිකරුවන්ට දීමට", "පුරාවිද්‍යා උරුමයේ වටිනාකම ප්‍රජාව අවබෝධ කර ගැනීමෙන් චිත්‍ර විනාශ වීම වැළකේ."),
        q("පුරාශිලා ගුහා චිත්‍රවල දක්නට ලැබෙන 'කළු මැංගනීස්' වර්ණකය පොළොවෙන් සොයා ගෙන සැකසීමෙන් පෙනෙන මානව කුසලතාව කුමක්ද?", "ප්‍රාථමික ඛනිජ හඳුනාගැනීමේ හා වර්ණ තාක්ෂණික දැනුම", "කෘත්‍රිම රසායනාගාර පවත්වාගෙන යාම", "නවීන පතල් කැණීමේ යන්ත්‍ර භාවිතය", "ලෝහ උණු කිරීමේ විදුලි උදුන් භාවිතය", "ස්ථායී හා නොමැකෙන වර්ණ ලබා දෙන ඛනිජ පාෂාණ තෝරාගෙන කුඩු කිරීමේ දැනුම ඔවුන් සතු විය."),
        q("නවශිලා යුගයේ චිත්‍ර හා මැටි බඳුන්වල 'සර්පිලාකාර රටා' (Spirals) නිරූපණය වීමෙන් හඟවන පොදු සංකේතාර්ථය කුමක්ද?", "ජලය, කාල චක්‍රය හා ජීවිතයේ අඛණ්ඩතාව", "වෙළඳසැල්වල මිල ගණන්", "රාජ්‍ය හමුදා සංඛ්‍යා ලේඛන", "නූතන ගෘහ විදුලි පරිපථ", "ලෝකයේ බොහෝ නවශිලා ශිෂ්ටාචාරවල සර්පිල හා රැලි රටා ජලය හා ස්වභාවික චක්‍රය සංකේතවත් කළේය."),
        q("ශ්‍රී ලංකාවේ ආදි ගුහා සිතුවම් අතර 'පුරාණ විහාර බිතුසිතුවම්වලට' වඩා වෙනස් වන්නේ කුමන ලක්ෂණයකින්ද?", "ආගමික කතා පුවත් වෙනුවට දඩයම් හා සංකේත පමණක් තිබීම", "ජල සායම් හා ඇක්‍රිලික් වර්ණ යොදා තිබීම", "විශාල රන් ආලේපිත බුදු රූප තිබීම", "සෑම චිත්‍රයකම සිංහල කවි ලියා තිබීම", "බෞද්ධ විහාර චිත්‍ර ජාතක කතා හා සැරසිලි මත පදනම් වන අතර ආදි ලෙන් චිත්‍ර දඩයම් හා සංකේතවලට සීමා වේ."),
        q("ආදි ගුහා සිතුවම්කරණයේදී 'කලාකරුවා පරිසරයට ගරු කළ' බව සනාථ වන කරුණ කුමක්ද?", "ගල් බිත්ති සමතලා නොකර ස්වභාවික හැඩය තුළම ඇඳීම", "විශාල ගස් කපා ගුහාවල තැබීම", "සතුන් සියල්ල ගුහා ඇතුළත සිර කර තැබීම", "රසායනික අපද්‍රව්‍ය ගංගාවලට මුදා හැරීම", "ගල් පර්වතයේ ස්වභාවික පිහිටීමට හානි නොකර එහි නෙරීම් භාවිතයෙන් රූප මැවීම විශේෂත්වයකි."),
        q("ලොව ප්‍රකට ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර අධ්‍යයනයේදී 'ලැස්කෝ' ගුහාව හඳුන්වනු ලබන තවත් විශේෂිත නාමයක් කුමක්ද?", "ප්‍රාග් ඓතිහාසික ලෝකයේ මහා කලාගාරය", "පුරාණ ග්‍රීක පුස්තකාලය", "රෝම අධිරාජ්‍යයේ කෞතුකාගාරය", "මධ්‍යකාලීන රාජ මාලිගාව", "වර්ණවත් හා ජවසම්පන්න සත්ව රූප 600කට අධික සංඛ්‍යාවක් නිසා එය ආදි කලාගාරයක් ලෙස සැලකේ.")
    )
}
